using namespace hyperion;namespace hf=hyperion::flight;
namespace {
int checks=0;void check(bool value,const char* why){checks++;if(!value)throw std::runtime_error(why);}
bool close(double a,double b){return std::abs(a-b)<1e-6;}
void free(Game& g){auto& f=g.s.flight;f.docked=f.deployed=false;f.dockedPort=-1;f.savedDock.clear();f.cancelNavigation();f.launchAssist=0;f.ship.velocity={};f.ship.throttle=0;g.s.economy.docked.clear();}
std::string fixture(Game& g,int kind=Warehouse,bool orbit=false,int owner=1){g.enterFlight();auto& e=g.s.economy;auto& site=e.settlements.front();site.owner=owner;site.stock.fill(10);site.built[kind]=std::max(1,site.built[kind]);site.built[Fabricator]=1;site.built[Solar]=4;g.ensureFlight();e.missions.clear();e.missionClock.clear();e.captains.clear();e.pirates.clear();g.s.flight.traffic.clear();auto port=g.s.flight.ports[g.flightPort(site.id,orbit)];free(g);g.s.flight.ship.position=port.position+port.normal*100;Stock kit{};kit[Components]=30;kit[Crystal]=10;kit[Medicine]=8;g.storeShipStock(kit);e.credits=100000;return orbit?portObjectId(port.id):facilityObjectId(site.id,kind,0);}
void damage(Game& g,const std::string& id){g.prepareWorldObjects();for(int i=0;i<int(g.s.flight.worldObjects.size());i++)if(g.s.flight.worldObjects[i].id==id){auto p=g.s.flight.worldObjects[i].position;g.s.flight.damageWorld(i,1e8,-1,p,false,"environment");g.processFlightEvents();return;}throw std::runtime_error("Missing wreck fixture");}
void approach(Game& g,const std::string& id){free(g);auto& d=g.s.economy.worldDamage.at(id);g.s.flight.ship.position=d.position+d.normal*45;}
void clock(Game& g,double hour){g.s.hours=g.s.economy.hour=hour;g.advanceRecoverySociety(false);g.recoveryMissions();}
void roundtrip(Game& g){auto j=encodeEconomy(g.s.economy);check(encodeEconomy(decodeEconomy(j,g.universe,g.s.hours))==j,"Society state did not roundtrip exactly");}
int people(const Game& g){auto& e=g.s.economy;int n=e.colonists;for(const auto& p:e.settlements)n+=p.residents;for(const auto& f:e.factions)n+=f.reservePopulation;for(const auto& c:e.recoveryCrews)n+=c.people;for(const auto& [id,d]:e.worldDamage)n+=d.recovery.crew+d.recovery.aboard+d.recovery.npcAboard;for(const auto& [id,b]:e.boardings)n+=b.party+b.defenders;for(const auto& w:e.oceanWrecks)n+=w.crew+w.aboard;return n;}
Stock worldStock(const Game& g){Stock s{};for(const auto& p:g.s.economy.settlements)for(int i=0;i<goodCount;i++)s[i]+=p.stock[i];for(const auto& c:g.s.economy.recoveryCrews)for(int i=0;i<goodCount;i++)s[i]+=c.cargo[i];for(const auto& [id,d]:g.s.economy.worldDamage)for(int i=0;i<goodCount;i++)s[i]+=d.salvage[i]+d.recovery.sealed[i];return s;}
std::string disabled(Game& g,bool pirate=false){fixture(g,Warehouse,true,1);auto& e=g.s.economy;Captain c;c.id="boarding-fixture";c.name="Vesper";c.star=g.s.currentStar;c.home=e.settlements.front().id;c.faction=1;c.role=1;c.genome={1,231143,false};c.modules={0,100,10};c.hull=60;c.shield=0;e.captains.push_back(c);if(pirate){PirateBand band;band.id="BOARD-PIRATES";band.name="Vesper crew";band.star=g.s.currentStar;band.haven=c.home;band.stock.fill(10);band.treasury=1000;e.pirates.push_back(band);e.captains.back().band=band.id;g.s.flight.worldKey.clear();g.ensureFlight();g.s.flight.traffic.erase(std::remove_if(g.s.flight.traffic.begin(),g.s.flight.traffic.end(),[&](const auto& t){return t.id!=c.id;}),g.s.flight.traffic.end());}g.refreshSecurity();auto& t=g.s.flight.traffic.back();t.position=t.previous=g.s.flight.ship.position+g.s.flight.ship.forward*30;t.positioned=true;t.velocity={};t.forward=-g.s.flight.ship.forward;t.hostile=true;t.pirate=pirate;g.s.flight.combatTarget=t.id;g.openStrategy();return t.id;}
void begin(Game& g,const std::string& id){check(g.boardingQuote("boardingBegin",id).available,"Cannot board disabled fixture");g.action("boardingBegin",id);check(g.s.economy.boardings.at(id).status==0,"Boarding party did not remain attached");}
}
